import json

input_grid = [[int(x) for x in row.split()] for row in demo_input_str.strip().split('\n')]
output_grid = [[int(x) for x in row.split()] for row in demo_output_str.strip().split('\n')]

def get_layer(r, c, r_start, r_end, c_start, c_end):
    return min(r - r_start, r_end - r, c - c_start, c_end - c)

def get_layer_color_mapping(grid_in, grid_out, container):
    """Compute the layer -> color_mapping for a container"""
    layer_color_map = {}

    for r in range(container['r_start'], container['r_end'] + 1):
        for c in range(container['c_start'], container['c_end'] + 1):
            if grid_in[r][c] != 0:
                layer = get_layer(r, c, container['r_start'], container['r_end'], 
                                  container['c_start'], container['c_end'])
                color_in = grid_in[r][c]
                color_out = grid_out[r][c]

                if layer not in layer_color_map:
                    layer_color_map[layer] = {}
                if color_in not in layer_color_map[layer]:
                    layer_color_map[layer][color_in] = color_out
    return layer_color_map

containers = [
    {'r_start': 1, 'r_end': 13, 'c_start': 2, 'c_end': 11},
    {'r_start': 4, 'r_end': 10, 'c_start': 6, 'c_end': 11},
    {'r_start': 2, 'r_end': 7, 'c_start': 13, 'c_end': 18},
]

layer_maps = []

for i, container in enumerate(containers):
    mapping = get_layer_color_mapping(input_grid, output_grid, container)
    print(f"\nContainer {i+1} [{container['r_start']},{container['r_end']}] x [{container['c_start']},{container['c_end']}]:")
    for layer in sorted(mapping.keys()):
        print(f"  Layer {layer}: {mapping[layer]}")
    layer_maps.append(mapping)

# Now let me verify by applying these transforms to the input
def apply_transformation(grid_in, grid_out, containers, layer_maps):
    """Apply layer-based color transformation to grid"""
    result = [[grid_in[r][c] for c in range(len(grid_in[0]))] for r in range(len(grid_in))]

    for i, container in enumerate(containers):
        mapping = layer_maps[i]
        r_start = container['r_start']
        r_end = container['r_end']
        c_start = container['c_start']
        c_end = container['c_end']

        for r in range(r_start, r_end + 1):
            for c in range(c_start, c_end + 1):
                if grid_in[r][c] != 0:
                    layer = get_layer(r, c, r_start, r_end, c_start, c_end)
                    if layer in mapping and grid_in[r][c] in mapping[layer]:
                        result[r][c] = mapping[layer][grid_in[r][c]]

    return result

# Apply transformation and compare
applied_output = apply_transformation(input_grid, output_grid, containers, layer_maps)

# Check if correct
matches = True
for r in range(len(input_grid)):
    for c in range(len(input_grid[0])):
        if input_grid[r][c] != 0 or output_grid[r][c] != 0:
            if applied_output[r][c] != output_grid[r][c]:
                print(f"Mismatch at ({r},{c}): applied={applied_output[r][c]}, expected={output_grid[r][c]}")
                matches = False

if matches:
    print("\nTransformation matches output grid!")

