def get_all_containers(grid_lines, name_prefix=""):
    containers = []
    # Find top-left of each container
    for r in range(len(grid_lines)):
        for c in range(len(grid_lines[r])):
            if grid_lines[r][c] != '0' and (c == 0 or grid_lines[r][c-1] == '0'):
                val = int(grid_lines[r][c])
                # Expand right to find container width
                container = {
                    'top': r,
                    'left': c,
                    'value': val
                }
                for cc in range(c, len(grid_lines[r])):
                    if grid_lines[r][cc] == '0':
                        break
                    elif grid_lines[r][cc] == str(val):
                        container['left'] = cc
                    else:
                        container['left'] = c
                        break
                # Expand down to find container height
                container['right'] = c
                for rr in range(r, len(grid_lines)):
                    if grid_lines[rr][c] == '0':
                        break
                    container['bottom'] = rr
                containers.append(container)
    return containers

def find_containers_v2(grid):
    """Find container rectangles by looking for changed cells"""
    containers = []
    found_regions = set()

    for r in range(1, len(grid)-1):
        for c in range(1, len(grid[0])-1):
            val = grid[r][c]
            if val != '0' and val not in found_regions:
                # Check if this is start of a container (edge)
                found_regions.add(val)
                rs, re, cs, ce = r, r, c, c
                # Find boundaries
                for carbon in range(r, len(grid)):
                    if grid[carbon][c] == '0':
                        re = carbon - 1
                        break
                for carbon in range(r, len(grid)):
                    if carbon < re and grid[carbon][18] == '0':
                        ce = carbon - 1
                        break
                for col in range(1, 19):
                    if grid[r][col] == '0':
                        cs = col - 1
                        break
                for col in range(1, 19):
                    if col < ce and grid[19][col] == '0':
                        ce = col - 1
                        break
                containers.append((rs, re, cs, ce))
    return containers

