def parse_container(grid):
    containers = []
    for r in range(1, len(grid)-1):
        for c in range(1, len(grid[r])-1):
            if grid[r][c] != '0':
                val = int(grid[r][c])
                # Find this container's bbox
                rs, re = r, r
                for rr in range(r, len(grid)):
                    if grid[rr][c] == '0':
                        break
                    re = rr
                cs, ce = c, c
                for cc in range(c, len(grid[r])):
                    if grid[r][cc] == '0':
                        break
                    ce = cc
                containers.append((rs, re, cs, ce, val))
    return containers

